export default {
  id: ID,
  name: 'Hail Hermes',
  description: 'Try Hermes on your wrist from the desktop: approve watches, hold-to-talk, and a bundled sample question.',
  defaultEnabled: true,
  register(ctx) {
    ctx.i18n.register({ en: EN })
    ctx.onDispose(() => {
      if (closeWorkspace) closeWorkspace()
      closeWorkspace = null
      toggleMini = null
    })
    ctx.register({
      id: 'toggle-mini',
      area: KEYBINDS_AREA,
      data: {
        id: 'hail-hermes.toggle-mini', category: 'view', defaults: ['alt+shift+h'],
        label: 'Toggle Hail Hermes', run: () => toggleMini?.()
      }
    })
    // The left rail: one entry, one page. Hail Hermes stops being reachable only through a status-bar
    // chip and a keybind, which is what made it feel bolted on.
    ctx.register({
      id: 'nav',
      area: SIDEBAR_NAV_AREA,
      order: 45,
      data: { path: '/hail', label: 'Hail Hermes', codicon: 'watch' }
    })
    ctx.register({
      id: 'page',
      area: ROUTES_AREA,
      order: 45,
      data: { path: '/hail' },
      render: () => jsx(WristPage, { ctx })
    })
    ctx.register({
      id: 'wrist-status',
      area: STATUSBAR_AREAS.right,
      order: 90,
      render: () => jsx(WristStatusChip, { ctx })
    })
    // The build stamp lives inside the pane (header + Settings), not as a second status-bar item:
    // two copies of the same line in one status bar is clutter, and the pane is where someone looks
    // when they are asking "which build am I running".
  }
}
